// generated from rosidl_adapter/resource/msg.idl.em
// with input from omni_robot_interfaces/msg/AutonomyRuntimeStatus.msg
// generated code does not contain a copyright notice

#include "builtin_interfaces/msg/Time.idl"

module omni_robot_interfaces {
  module msg {
    module AutonomyRuntimeStatus_Constants {
      @verbatim (language="comment", text=
        "对外能力模式。数值同时冻结在 SetAutonomyMode.Request 中。")
      const uint8 MODE_IDLE = 0;
      const uint8 MODE_MAPPING = 1;
      const uint8 MODE_LOCALIZATION_READY = 2;
      const uint8 MODE_SINGLE_POINT_READY = 3;
      const uint8 MODE_INSPECTION_READY = 4;
      const uint8 MODE_ROUTE_RECORDING = 5;
      @verbatim (language="comment", text=
        "全局转换阶段。READY 只表示当前 mode 的全部不变量均已满足。")
      const uint8 PHASE_IDLE = 0;
      const uint8 PHASE_STARTING = 1;
      const uint8 PHASE_READY = 2;
      const uint8 PHASE_SWITCHING = 3;
      const uint8 PHASE_STOPPING = 4;
      const uint8 PHASE_ERROR = 5;
      const uint8 PHASE_CONFLICT = 6;
      @verbatim (language="comment", text=
        "从 /omni/slam/status 和进程监督器派生的 SLAM 状态。该字段独立于 mode，" "\n"        "因而可以表达“Planner 正在切换但定位仍然可用”等真实中间态。")
      const uint8 SLAM_UNKNOWN = 0;
      const uint8 SLAM_STOPPED = 1;
      const uint8 SLAM_STARTING_MAPPING = 2;
      const uint8 SLAM_MAPPING = 3;
      const uint8 SLAM_SAVING = 4;
      const uint8 SLAM_MAP_READY = 5;
      const uint8 SLAM_STARTING_LOCALIZATION = 6;
      const uint8 SLAM_RELOCALIZING = 7;
      const uint8 SLAM_LOCALIZED = 8;
      const uint8 SLAM_DEGRADED = 9;
      const uint8 SLAM_LOST = 10;
      const uint8 SLAM_STOPPING = 11;
      const uint8 SLAM_ERROR = 12;
      const uint8 SLAM_CONFLICT = 13;
      @verbatim (language="comment", text=
        "Mission Manager 唯一托管的 Planner 进程组状态。mode 1 与 mode 3 不能并存；" "\n"        "检测到非本 Manager 所有的实例时必须进入 CONFLICT，禁止越权结束外部进程。")
      const uint8 PLANNER_UNKNOWN = 0;
      const uint8 PLANNER_STOPPED = 1;
      const uint8 PLANNER_STARTING_SINGLE_POINT = 2;
      const uint8 PLANNER_SINGLE_POINT_READY = 3;
      const uint8 PLANNER_STARTING_INSPECTION = 4;
      const uint8 PLANNER_INSPECTION_READY = 5;
      const uint8 PLANNER_STOPPING = 6;
      const uint8 PLANNER_ERROR = 7;
      const uint8 PLANNER_CONFLICT = 8;
      @verbatim (language="comment", text=
        "路线录制器与 Planner 是两个独立组件；路线录制时 Planner 通常保持 STOPPED。")
      const uint8 ROUTE_RECORDING_IDLE = 0;
      const uint8 ROUTE_RECORDING_STARTING = 1;
      const uint8 ROUTE_RECORDING_ACTIVE = 2;
      const uint8 ROUTE_RECORDING_STOPPING = 3;
      const uint8 ROUTE_RECORDING_ERROR = 4;
      const uint8 ROUTE_RECORDING_CONFLICT = 5;
      @verbatim (language="comment", text=
        "自主运行时公共原因码。下游模块若有更具体的稳定原因码，可以原样透传。")
      const uint32 REASON_NONE = 0;
      const uint32 REASON_INVALID_REQUEST = 4000;
      const uint32 REASON_STALE_SEQUENCE = 4001;
      const uint32 REASON_UNSUPPORTED_MODE = 4002;
      const uint32 REASON_BUSY = 4003;
      const uint32 REASON_EXTERNAL_CONFLICT = 4004;
      const uint32 REASON_MAP_REQUIRED = 4005;
      const uint32 REASON_MAP_MISMATCH = 4006;
      const uint32 REASON_SLAM_UNAVAILABLE = 4007;
      const uint32 REASON_PLANNER_UNAVAILABLE = 4008;
      const uint32 REASON_OPERATION_FAILED = 4009;
      const uint32 REASON_NOT_MAPPING = 4010;
      const uint32 REASON_SAVE_FAILED = 4011;
      const uint32 REASON_TIMEOUT = 4012;
      const uint32 REASON_NOT_RECORDING = 4013;
      const uint32 REASON_ROUTE_SAVE_FAILED = 4014;
      const uint32 REASON_EXPIRED = 4015;
      const uint32 REASON_ROUTE_ID_CONFLICT = 4016;
    };
    @verbatim (language="comment", text=
      "机器人自主运行时的权威状态快照。" "\n"
      "" "\n"
      "Producer : omni_mission_manager" "\n"
      "Consumers: App、Bridge、运维诊断" "\n"
      "Topic    : /omni/mission/runtime/status" "\n"
      "QoS      : reliable + transient_local，depth=1；另按固定周期发送心跳。" "\n"
      "" "\n"
      "mode 表示当前已经由运行时依赖和遥测证明成立的模式；desired_mode 表示当前" "\n"
      "操作希望到达的目标模式。切换期间二者可以不同，消费者不得仅凭进程存在就" "\n"
      "把 desired_mode 当成 READY。")
    struct AutonomyRuntimeStatus {
      builtin_interfaces::msg::Time stamp;

      uint8 mode;

      uint8 desired_mode;

      uint8 phase;

      uint8 slam_state;

      uint8 planner_state;

      uint8 route_recording_state;

      @verbatim (language="comment", text=
        "ready=true 等价于 phase=READY 且当前非空闲 mode 的所有依赖均已通过健康门禁。" "\n"
        "稳定空闲态使用 phase=IDLE、ready=false。mission_active 只描述任务执行，" "\n"
        "不描述 Planner/SLAM 进程是否常驻。")
      boolean ready;

      boolean mission_active;

      @verbatim (language="comment", text=
        "最近一次被受理或正在执行的请求身份。没有请求时三项为空/零。")
      string request_id;

      uint64 request_sequence;

      string request_source;

      @verbatim (language="comment", text=
        "manager_epoch 在 Mission Manager 每次进程启动时重新生成；客户端发现 epoch" "\n"
        "变化后必须丢弃旧 operation_id。runtime_generation 在新的非幂等运行时转换" "\n"
        "被受理时预留并递增，整个转换期间保持不变；status_sequence 在同一 epoch" "\n"
        "内每次发布严格递增。")
      string manager_epoch;

      uint64 runtime_generation;

      uint64 status_sequence;

      string operation_id;

      @verbatim (language="comment", text=
        "当前已解析并校验的地图资产。version=0、checksum 为空表示尚无有效资产。")
      string map_id;

      uint32 map_version;

      string map_checksum;

      uint32 reason_code;

      string reason_text;

      @verbatim (language="comment", text=
        "V1 additive 扩展：当前路线录制资产的权威摘要。字段只能在消息尾部追加，" "\n"
        "以保留此前已冻结字段的声明顺序。非路线录制模式下 route_id/checksum 为空、" "\n"
        "数值为 0、route_has_unsaved_data=false；录制过程中 point/distance 可递增。")
      string route_id;

      uint32 route_point_count;

      float route_distance_m;

      string route_checksum;

      boolean route_has_unsaved_data;

      @verbatim (language="comment", text=
        "当前路线录制会话的稳定 operation identity。FinishRouteRecording 自己产生的" "\n"
        "operation_id 不得覆盖该值；进程冷恢复在 ERROR 阶段仍依赖它 SAVE/DISCARD。" "\n"
        "没有活动或待收口的路线录制会话时为空。")
      string recording_operation_id;
    };
  };
};

