// with input from omni_robot_interfaces/msg/RobotState.msg
// generated code does not contain a copyright notice

#include "std_msgs/msg/Header.idl"

module omni_robot_interfaces {
  module msg {
    module RobotState_Constants {
      @verbatim (language="comment", text=
        "--- operational mode: what the robot is doing overall ---")
      const uint8 MODE_IDLE = 0;
      const uint8 MODE_MAPPING = 1;
      const uint8 MODE_LOCALIZING = 2;
      const uint8 MODE_MISSION = 3;
      const uint8 MODE_DOCKING = 4;
      const uint8 MODE_ESTOP = 5;
      @verbatim (language="comment", text=
        "--- control authority: who holds the motion lease ---" "\n"        "Must match the arbiter owner kinds (app / mission / docking).")
      const uint8 AUTHORITY_NONE = 0;
      const uint8 AUTHORITY_APP = 1;
      const uint8 AUTHORITY_MISSION = 2;
      const uint8 AUTHORITY_DOCKING = 3;
      @verbatim (language="comment", text=
        "--- localization (relayed from SLAM manager SlamStatus) ---")
      const uint8 LOC_UNKNOWN = 0;
      const uint8 LOC_DEGRADED = 1;
      const uint8 LOC_LOST = 2;
      const uint8 LOC_LOCALIZED = 3;
      @verbatim (language="comment", text=
        "--- health ---")
      const uint8 HEALTH_OK = 0;
      const uint8 HEALTH_WARN = 1;
      const uint8 HEALTH_FAULT = 2;
      @verbatim (language="comment", text=
        "--- mission (relayed from the Mission Manager snapshot) ---" "\n"        "Values MUST match MissionStatus.MISSION_*.")
      const uint8 MISSION_NONE = 0;
      const uint8 MISSION_PENDING = 1;
      const uint8 MISSION_EXECUTING = 2;
      const uint8 MISSION_PAUSED = 3;
      const uint8 MISSION_SUCCEEDED = 4;
      const uint8 MISSION_CANCELED = 5;
      const uint8 MISSION_FAILED = 6;
      const uint8 MISSION_INTERRUPTED = 7;
    };
    @verbatim (language="comment", text=
      "Whole-robot snapshot. Single source of truth for \"what is the robot doing" "\n"
      "and who may move it right now\"." "\n"
      "" "\n"
      "Producer : gateway (rosdeck_robot_bridge), 1 Hz + on change" "\n"
      "Consumers: App, Mission Manager, Safety Supervisor" "\n"
      "Topic    : /omni/robot_state  (reliable, transient_local)")
    struct RobotState {
      std_msgs::msg::Header header;

      uint8 operational_mode;

      uint8 control_authority;

      @verbatim (language="comment", text=
        "e.g. \"app-<uuid>\", \"mission-<mission_id>\"")
      string authority_client_id;

      @verbatim (language="comment", text=
        "< 0 when no lease is held")
      float authority_lease_remaining_sec;

      uint8 localization_state;

      string map_id;

      string map_version;

      @verbatim (language="comment", text=
        "NaN when no fresh value")
      float localization_fitness_score;

      uint8 health_level;

      string health_summary;

      @verbatim (language="comment", text=
        "--- safety / motion ---" "\n"
        "fail-closed latch in the arbiter")
      boolean estop_latched;

      @verbatim (language="comment", text=
        "!estop_latched && a valid lease is held")
      boolean motion_authorized;

      uint8 mission_state;

      string mission_id;

      @verbatim (language="comment", text=
        "0..1, NaN when no mission")
      float mission_progress;

      @verbatim (language="comment", text=
        "--- power ---")
      float battery_voltage;

      @verbatim (language="comment", text=
        "NaN when unknown")
      float battery_percentage;

      boolean charging;
    };
  };
};

